useSeoPage('Dashboard', 'Your 247URL dashboard overview.', '/dashboard')
interface Summary { total_links: number; total_clicks: number; clicks_today: number; clicks_this_month: number; recent_links: LinkRecord[]; top_links: LinkRecord[] }
const { data, pending, error, refresh } = await useFetch<ApiEnvelope<Summary>>('/api/backend/dashboard')
</script>
<template><div><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="eyebrow">Overview</p><h1 class="mt-2 text-3xl font-black">Your link activity</h1></div><NuxtLink to="/dashboard/links/create" class="btn-primary">Create link</NuxtLink></div><LoadingState v-if="pending" class="mt-8"/><div v-else-if="error" class="surface mt-8 p-6"><h2 class="font-bold">Dashboard unavailable</h2><p class="mt-2 text-slate-400">Verify your email or try loading the dashboard again.</p><button class="btn-secondary mt-4" @click="() => refresh()">Try again</button></div><template v-else-if="data"><div class="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Total links" :value="data.data.total_links"/><StatCard label="Total clicks" :value="data.data.total_clicks.toLocaleString()"/><StatCard label="Clicks today" :value="data.data.clicks_today.toLocaleString()"/><StatCard label="This month" :value="data.data.clicks_this_month.toLocaleString()"/></div><div class="mt-10 grid gap-8 xl:grid-cols-2"><section><div class="mb-4 flex items-center justify-between"><h2 class="text-xl font-bold">Recent links</h2><NuxtLink to="/dashboard/links" class="text-sm text-teal-300">View all</NuxtLink></div><div class="surface divide-y divide-white/10"><div v-for="link in data.data.recent_links" :key="link.id" class="flex items-center justify-between gap-4 p-4"><div class="min-w-0"><p class="truncate font-semibold">{{ link.title || link.short_code }}</p><p class="truncate text-sm text-slate-500">{{ link.destination_url }}</p></div><span class="shrink-0 text-sm font-bold">{{ link.clicks_count }} clicks</span></div></div></section><section><h2 class="mb-4 text-xl font-bold">Quick create</h2><UrlShortenerForm /></section></div></template></div></template>
